import json,struct
from pathlib import Path
from unittest.mock import patch
import fq_symmetric_jacobi_support_20261122 as support
from flagquantum.compiler.optimization import two_qubit_synthesis as synthesis
calls=[]
def packed(result):
 return b''.join(struct.pack('!d',x) for x in result[0])+b''.join(struct.pack('!d',x) for row in result[1] for x in row)
def observed(matrix):
 before=support.FUNCTIONS['baseline'](matrix)
 after=support.FUNCTIONS['candidate'](matrix)
 asymmetry=max(abs(matrix[i][j]-matrix[j][i]) for i in range(4) for j in range(4))
 calls.append({'asymmetry':asymmetry,'bitwise_equal':packed(before)==packed(after),'value_max_error':max(abs(a-b) for a,b in zip(before[0],after[0]))})
 return after
source=support.fixture(6,'qft','grid',support.NONCES[0]);payloads={}
for variant in ('baseline','candidate'):
 with support.selected(variant):
  if variant=='candidate':
   with patch.object(synthesis,'_jacobi_eigh',observed):
    payload=support.adapter_for('flagquantum-target-artifact').execute('route',source,11)
  else:payload=support.adapter_for('flagquantum-target-artifact').execute('route',source,11)
 payloads[variant]=payload
metrics={v:support.accept(p,source) for v,p in payloads.items()}
report={'scope':'Untimed diagnosis after first resource-run equality refusal; no timing retry or resource admission','case':[6,'qft','grid'],'metrics':metrics,'operations_equal':payloads['baseline']['operations']==payloads['candidate']['operations'],'final_layout_equal':payloads['baseline']['final_layout']==payloads['candidate']['final_layout'],'calls':calls,'driver':Path(__file__).read_text()}
Path('/private/tmp/fq-symmetric-jacobi-diagnosis-20261122.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps({k:v for k,v in report.items() if k not in ('calls','driver')}))
print(json.dumps({'calls':len(calls),'asymmetric_inputs':sum(r['asymmetry']!=0 for r in calls),'different_results':sum(not r['bitwise_equal'] for r in calls),'max_asymmetry':max(r['asymmetry'] for r in calls)}))

